<script setup>import{Head,Link}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';defineProps({player:Object});</script><template><Head :title="player.name"/><AppLayout><Link href="/team-lab" class="text-sm font-bold text-[#66766e]">← Back to Team Lab</Link><div class="mt-5 overflow-hidden rounded-3xl bg-[#143c2b] text-white"><div class="grid gap-8 p-8 sm:p-11 lg:grid-cols-[1fr_1.5fr]"><div><span class="label !text-[#f4d35e]">Player report</span><h1 class="mt-3 text-5xl font-black">{{player.name}}</h1><p class="mt-2 text-white/55">{{player.full_name}} · {{player.team}}</p><div v-if="player.news" class="mt-6 rounded-xl bg-amber-300/15 p-4 text-sm text-amber-200">{{player.news}}</div></div><div class="grid grid-cols-2 gap-4 sm:grid-cols-4"><div class="rounded-2xl bg-white/7 p-4"><span class="label !text-white/45">Price</span><b class="mt-2 block text-2xl">£{{(player.price/10).toFixed(1)}}</b></div><div class="rounded-2xl bg-white/7 p-4"><span class="label !text-white/45">Form</span><b class="mt-2 block text-2xl">{{player.form}}</b></div><div class="rounded-2xl bg-white/7 p-4"><span class="label !text-white/45">Points</span><b class="mt-2 block text-2xl">{{player.points}}</b></div><div class="rounded-2xl bg-white/7 p-4"><span class="label !text-white/45">Owned</span><b class="mt-2 block text-2xl">{{player.ownership}}%</b></div></div></div></div><div class="mt-7 grid gap-7 lg:grid-cols-[1.5fr_1fr]"><section class="card p-7"><h2 class="text-xl font-black">Next five fixtures</h2><div class="mt-5 grid gap-3 sm:grid-cols-5"><div v-for="f in player.fixtures" class="rounded-2xl p-4 text-center" :class="f.difficulty<=2?'bg-emerald-100 text-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-200':f.difficulty>=4?'bg-red-100 text-red-700 dark:bg-red-950/40 dark:text-red-200':'bg-slate-100 dark:bg-slate-800'"><span class="label">GW{{f.gameweek}}</span><b class="mt-2 block text-lg">{{f.opponent}}</b><span class="text-xs">{{f.venue}} · FDR {{f.difficulty}}</span></div></div></section><section class="card p-7"><h2 class="text-xl font-black">Advisor view</h2><div class="mt-5 flex items-center gap-4"><span class="grid size-16 place-items-center rounded-2xl bg-[#f4d35e] text-2xl font-black text-[#173426]">{{player.score}}</span><div><span class="label">Recommendation score</span><p class="text-sm text-[#718078]">Form, minutes, price and fixtures</p></div></div><ul class="mt-5 space-y-2 text-sm"><li v-for="r in player.reasons">✓ {{r}}</li></ul></section></div></AppLayout></template>
